const fs = require('fs');
const ws = fs.createWriteStream('app.conf');
let failed = false;
ws.on('open', () => {
  ws.write('mode=dev\n');
  ws.emit('error', new Error('Producer failed after partial write'));
});
ws.on('error', (err) => {
  failed = true;
  console.log('FAIL: ' + err.message);
});
ws.on('close', () => {
  console.log(failed ? 'CORRUPTED' : 'OK');
  process.exit(0);
});
EOF

