const fs = require('fs');
const ws = fs.createWriteStream('app.conf.staging');
let failed = false;
ws.on('open', () => {
  ws.write('mode=dev\n');
  ws.emit('error', new Error('Producer failed after partial write'));
});
ws.on('error', (err) => {
  failed = true;
  console.log('FAIL: ' + err.message);
});
