  if (!failed) {
    fs.renameSync('app.conf.staging', 'app.conf');
    console.log('OK');
  } else {
    fs.unlinkSync('app.conf.staging');
    console.log('CORRUPTED_STAGING');
  }
  process.exit(0);
});
