const fs = require('fs');
const target = '/proj/app.conf';
const ws = fs.createWriteStream(target);
let step = 0;
const emit = () => {
  if (step === 0) {
    ws.write('beta=2\n');
    step++;
    setImmediate(emit);
  } else if (step === 1) {
    ws.write('gamma=3\n');
    step++;
    setImmediate(emit);
  } else {
    ws.end();
  }
};
ws.on('open', () => {
  console.log('OPEN');
  emit();
});
ws.on('drain', () => console.log('DRAIN'));
ws.on('error', (err) => {
  console.log('ERROR: ' + err.message);
  process.exitCode = 1;
});
ws.on('finish', () => {
  console.log('FINISH');
  process.exit(0);
});
