mkdir -p /proj
cd /proj
node <<'EOF'
const fs = require('fs');
const path = '/proj/app.json';
const stream = fs.createWriteStream(path);
const chunks = ['{"timeout":15,', '"retries":5}'];
let i = 0;
function next() {
  if (i < chunks.length) {
    stream.write(chunks[i]);
    i++;
    process.nextTick(next);
  } else {
    stream.end();
  }
}
stream.on('error', (err) => {
  console.error('Producer error:', err.message);
  process.exit(1);
});
stream.on('finish', () => {
  console.log('Done');
  process.exit(0);
});
next();
EOF

