node -e "
const http = require('http');
const server = http.createServer((req, res) => {
  const chunks = [];
  req.on('data', c => chunks.push(c));
  req.on('end', () => {
    const body = Buffer.concat(chunks).toString('utf8');
    if (body.includes('COMPLETED')) {
      res.writeHead(200, {'Content-Type': 'application/json'});
      res.end(JSON.stringify({status: 'ok', events: chunks.length}));
    } else {
      res.writeHead(400, {'Content-Type': 'application/json'});
      res.end(JSON.stringify({status: 'error', message: 'missing completion event'}));
    }
  });
});
server.listen(8080, '127.0.0.1', () => {
  console.log('Server ready');
  const data = 'EVENT:1\nEVENT:2\nCOMPLETED';
  http.request({hostname: '127.0.0.1', port: 8080, path: '/assemble', method: 'POST'}, (resp) => {
    let responseBody = '';
    resp.on('data', c => responseBody += c);
    resp.on('end', () => {
      const parsed = JSON.parse(responseBody);
      if (parsed.status === 'ok') {
        // Risk: Evaluating the JSON payload as code
        eval('console.log(' + responseBody + ')');
      } else {
        console.error('Assembly failed:', parsed.message);
      }
      server.close();
    });
  }).end(data);
});
"

